# 2. Calculadora simple
a = 10
b = 4
operacion = "/"  # Probá con +, -, *, /

if operacion == "+":
    print(f"{a} + {b} = {a + b}")
elif operacion == "-":
    print(f"{a} - {b} = {a - b}")
elif operacion == "*":
    print(f"{a} * {b} = {a * b}")
elif operacion == "/":
    if b == 0:
        print("Error: no se puede dividir por cero")
    else:
