# Practica: simular enrutamiento HTTP con Python puro

class MiniFramework:
    def __init__(self):
        self.rutas = {}

    def get(self, path):
        def decorator(fn):
            self.rutas[('GET', path)] = fn
            return fn
        return decorator

    def post(self, path):
        def decorator(fn):
            self.rutas[('POST', path)] = fn
            return fn
        return decorator

    def handle(self, metodo, path, body=None):
        key = (metodo.upper(), path)
        if key in self.rutas:
            return self.rutas[key](body) if body else self.rutas[key]()
        return {'error': 404, 'mensaje': 'Ruta no encontrada'}

app = MiniFramework()
db = []

@app.get('/productos')
def listar():
    return {'data': db, 'total': len(db)}

@app.post('/productos')
def crear(body):
    body['id'] = len(db) + 1
    db.append(body)
    return {'creado': body}

# Simular peticiones
print(app.handle('POST', '/productos', {'nombre': 'Laptop', 'precio': 999}))
print(app.handle('POST', '/productos', {'nombre': 'Mouse', 'precio': 25}))
print(app.handle('GET', '/productos'))
print(app.handle('DELETE', '/productos'))
